class Solution {
public:
    long long goodTriplets(vector<int>& nums1, vector<int>& nums2) {
        int n = nums1.size();
        vector<int> pos1(n);
        for (int i = 0; i < n; i++) pos1[nums1[i]] = i;

        vector<int> bit(n + 1, 0);
        auto update = [&](int i) {
            for (i++; i <= n; i += i & (-i)) bit[i]++;
        };
        auto query = [&](int i) -> int {
            int s = 0;
            for (i++; i > 0; i -= i & (-i)) s += bit[i];
            return s;
        };

        vector<long long> left(n), right(n);

        for (int i = 0; i < n; i++) {
            int y = nums2[i];
            int p = pos1[y];
            left[y] = query(p - 1);
            update(p);
        }

        fill(bit.begin(), bit.end(), 0);

        for (int i = n - 1; i >= 0; i--) {
            int y = nums2[i];
            int p = pos1[y];
            int total = n - 1 - i;
            right[y] = total - query(p);
            update(p);
        }

        long long ans = 0;
        for (int y = 0; y < n; y++) {
            ans += left[y] * right[y];
        }
        return ans;
    }
};
